INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D031_ABILITY','The Unfinished Atlas');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D031_ABILITY_HELP','Every ten previously unseen land plots discovered by your units give 15 Science and 10 Culture at Standard speed, ten rewards per era. Unspent progress carries forward. City-only discoveries are unavailable because their source cannot be verified.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D031_CIV_PEDIA','Meridian''s surveyors record what exists beyond the map''s edge. Elian Vey keeps a space on every map for discoveries yet to come.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D031_STRATEGY','Explore in different directions and keep scouts safe. Unlock naval exploration when the coast limits land discovery, and build Atlas Houses as the map fills in.');
